COD_CURSO_IN IN INT,
NOMBRE_IN IN VARCHAR2,
DESCRIPCION_IN IN VARCHAR2
)
is
BEGIN
insert into "CURSO"("COD_CURSO","NOMBRE","DESCRIPCION") values(COD_CURSO_IN,NOMBRE_IN,DESCRIPCION_IN);
