        /**/
        if not SQL%FOUND then
            v$msg := util.format(util.gettext('no se puede ejecutar este proceso en este momento porque se esta ejecutando otro proceso del grupo %s'), codigo);
            raise_application_error(v$err, v$msg, true);
        end if;
        /**/
    end if;
    return grupo;
end;
