#需求：邮箱必须保证唯一：
#表级约束：
# 语法：CONSTRAINT 约束名称 约束类型(字段名)
CONSTRAINT t_stu1_email_uk UNIQUE(email)
);

ALTER TABLE t_stu1
MODIFY email VARCHAR(30) NULL;

