INSERT INTO t_stu1 VALUES(1, '李四' ,null,'2020-01-01');

#主键约束：非空约束+唯一约束 ，用来表示表中的唯一的一条记录，不容许有重复
CREATE TABLE t_stu2(
sid INT ,                      #PRIMARY KEY
sname VARCHAR(20) NOT NULL,
