    SELECT j.username AS A, k.username AS B
    FROM followers j, followers k 
    WHERE j.followers = k.username
);

-- A follows B and B NOT follows A
INSERT INTO query1(
    (SELECT * FROM A2)
    EXCEPT
    (SELECT * FROM A1)
);

