          	ptype_count := 0;
          	counter := counter + 1;
			
		FOR order_no IN type_counter LOOP
			ptype_count:=ptype_count+1;
		END LOOP;
            
           	dbms_output.put_line(counter||' Pizza Type: '||ptype_count);
       		
	END LOOP;
END;
