INSTEAD OF UPDATE ON vw_rebellion
FOR EACH ROW
BEGIN
    UPDATE trainer SET full_name = :NEW.full_name WHERE full_name = :OLD.full_name;
    UPDATE subject SET sub_name = :NEW.sub_name WHERE sub_name = :OLD.sub_name;
END;
/
