CREATE OR REPLACE TRIGGER check_review BEFORE
    INSERT ON review
    FOR EACH ROW
DECLARE
    start_review     DATE;
    stay_completed   DATE;
BEGIN
    SELECT
        booking_to
    INTO stay_completed
    FROM
        booking
    WHERE
        guest_no = :new.guest_no;

    SELECT
        review_date
    INTO start_review
    FROM
        review
    WHERE
        guest_no = :new.guest_no;

    IF start_review > stay_completed THEN
        raise_application_error(-404,('Review can only be made after completed stay'
        ));
    END IF;
END;
