-- But check out the index sizes

select relname,
  pg_size_pretty(pg_relation_size(c.oid)) as "size"
from pg_class c
left join pg_namespace n on (n.oid = c.relnamespace)
where relname like 'sensor_samples%idx'
order by pg_relation_size(c.oid) desc;

