-- TAREA 01
-- Desarrollar un procedimiento que permita
-- consultar los ahorros en soles y dolares
-- en una sucursal.


CREATE OR REPLACE PROCEDURE EUREKA.PR_CON_AHORRO
(

suffix:
  P_AHORRO_SOLES   OUT NUMBER,
  P_AHORRO_DOLARES OUT NUMBER,
  P_MENSAJE        OUT VARCHAR2
)
IS
  V_CONT NUMBER(5);
BEGIN

  -- Validar
  SELECT COUNT(1) INTO V_CONT 
  FROM EUREKA.SUCURSAL 
  WHERE CHR_SUCUCODIGO = P_SUCURSAL;

  IF V_CONT <> 1 THEN
    P_MENSAJE := 'NO EXISTE LA SUCURSAL.';
    RETURN;
  END IF;

  -- PROCESO
  SELECT  
    NVL(SUM(CASE WHEN CHR_MONECODIGO='01' THEN DEC_CUENSALDO ELSE 0 END), 0),
    NVL(SUM(CASE WHEN CHR_MONECODIGO='02' THEN DEC_CUENSALDO ELSE 0 END), 0)
  INTO P_AHORRO_SOLES, P_AHORRO_DOLARES
  FROM EUREKA.CUENTA 
  WHERE CHR_SUCUCODIGO = P_SUCURSAL;

  P_MENSAJE := 'OK';
END;
/



BEGIN
  EUREKA.PR_CON_AHORRO ('002', :p_ahorro_soles$NUMBER, :p_ahorro_dolares$NUMBER, :p_mensaje$VARCHAR2);
END;

